<script setup lang="ts">import {computed,ref} from "vue";import {useRoute} from "vue-router";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import ConfirmDialog from "@/components/zs/ConfirmDialog.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta("Purchase Order Detail","Review approval, receiving and accounting impact for a purchase order.");const c=useCompanyStore(),route=useRoute(),s=useAsyncData(()=>operationsRepository.purchaseOrders(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),item=computed(()=>(s.data.value??[]).find(x=>x.id===route.params.id)),confirm=ref<"approve"|"receive"|"bill"|null>(null);const columns:Column[]=[{key:"description",header:"Description"},{key:"quantity",header:"Quantity",align:"right"},{key:"unit_cost",header:"Unit cost",align:"right"},{key:"total",header:"Line total",align:"right"}];async function run(){if(!item.value||!confirm.value)return;const status=confirm.value==='receive'?'received':'approved';if(confirm.value!=='bill')await operationsRepository.updatePurchaseStatus(c.activeCompanyId,item.value.id,status);showToast(confirm.value==='bill'?'Bill conversion preview ready':confirm.value==='receive'?'Goods receipt recorded':'Purchase order approved',confirm.value==='bill'?'No supplier bill is posted until the API confirms it.':undefined);confirm.value=null;await s.refresh()}</script><template><AppShell><template v-if="item"><PageHeader :title="item.number" :description="`${item.supplier} · Ordered ${item.date}`"><template #actions><StatusBadge :status="item.status"/><ZButton v-if="item.status==='pending'" @click="confirm='approve'">Approve</ZButton><ZButton v-if="item.status!=='received'" variant="outline" @click="confirm='receive'">Record receipt</ZButton><ZButton v-if="item.status==='received'" @click="confirm='bill'">Convert to bill</ZButton></template></PageHeader><div class="grid gap-4 xl:grid-cols-[1fr_22rem]"><Panel title="Order lines"><DataTable :columns="columns" :rows="item.lines.map((x,i)=>({...x,id:String(i),total:x.quantity*x.unit_cost}))" :min-width="620"><template #description="{row}">{{row.description}}</template><template #quantity="{row}">{{row.quantity}}</template><template #unit_cost="{row}">{{formatMoney(row.unit_cost)}}</template><template #total="{row}">{{formatMoney(row.total)}}</template></DataTable></Panel><div class="space-y-4"><Panel title="Order summary"><dl class="space-y-3 p-4 text-sm"><div class="flex justify-between"><dt class="text-content-muted">Owner</dt><dd>{{item.owner}}</dd></div><div class="flex justify-between"><dt class="text-content-muted">Expected</dt><dd>{{item.expected_date}}</dd></div><div class="flex justify-between"><dt class="text-content-muted">Received</dt><dd>{{item.received}}%</dd></div><div class="flex justify-between border-t border-line pt-3 font-semibold"><dt>Total</dt><dd>{{formatMoney(item.total)}}</dd></div></dl></Panel><Panel title="Accounting impact" description="Preview only until supplier bill posting"><div class="p-4 text-xs text-content-secondary"><p>Debit Inventory / Expense</p><p class="mt-2">Credit Accounts Payable</p><p class="mt-3 text-content-muted">The backend validates tax, period status and account mappings.</p></div></Panel></div></div><ConfirmDialog :open="!!confirm" :title="confirm==='approve'?'Approve purchase order':confirm==='receive'?'Record full receipt':'Create supplier bill preview'" :message="confirm==='bill'?'This prepares a supplier bill from the received order without posting it.':'This consequential action will update the preview workflow state.'" :confirm-label="confirm==='bill'?'Prepare bill':'Confirm'" @cancel="confirm=null" @confirm="run"/></template></AppShell></template>